var turl = match ? match[0] : null;  
var url = turl + result;  
java.log(url);  
var html = java.ajax(url);  
java.put('html', html);  
</js>  
body > div.main > div.infohead > div.cataloginfo > div.infotype > p:nth-child(2)@text##类型：

ruleToc.nextTocUrl:
@js:// 目录下一页规则
try {
  // 匹配第1/(\d+)关键词得到目录总页数
  var n = String(result).match(/第1[^\d]+(\d+)页/)[1];
  java.log(n);
  list = [];
  if (n == 1) {
    list;
  } else {
    for (i = 2; i <= n; i++) {
      turl = baseUrl.replace(/\/all_\d+\//, "/all_");
      list.push(turl + i + "/");
    }
  }
  list;
} catch (e) {}

