source.exploreUrl:
@js:
eval(String(source.variableComment))

const host = "http://www.78497.com"
const list = []

 // 添加榜单标题
  list.add("榜单", null, 1, 1)
  // 添加榜单单内容
  list.add("热门榜单", "https://m.baidu.com/#top1", 1, 0.4)
  list.add("特色音乐", "https://m.baidu.com/#top2", 1, 0.4)

categories.forEach(category => {
  let items = category.data.requestFilters.split("\n")

  // 添加歌单标题
  list.add(category.title, null, 0, 1)

  // 添加歌单内容
  items.forEach(item => {
    let [title, id] = item.split("::")
    let url = host + category.urlTemplate.replace("$id", id)
    list.add(title, url, 0, 0.29)
  })
})

JSON.stringify(list)

