const push = (arr, str, url) => {
  str.split("\n").forEach(item => {
  	  let [title, id] = item.split("::")
  	  arr.push(`<li class="name"><a href="${url.replace('$id', id)}">${title}</a></li>`)
  	})
}

const top1 = "酷狗飙升榜::kugou\nTOP排行榜::top\n抖音热歌榜::douyin\n快手热歌榜::kuaishou\nDJ热歌榜::djtop\n音乐分享榜::share\n内地排行榜::ndtop\n香港排行榜::hktop\n台湾排行榜::twtop\n欧美排行榜::ustop\n韩国排行榜::krtop";
const top2 = "ACG新歌榜::newacg\n电音热歌榜::dytop\n综艺新歌榜::newzy\n说唱先锋榜::sctop\n影视金曲榜::ystop\n粤语金曲榜::yytop\n欧美金曲榜::omtop\n音乐人原创榜::kkyc\n酷狗雷达榜::leida\n80后热歌榜::blhot\n90后热歌榜::jlhot";

const bookList = [];
const host = "http://www.78497.com"
const topUrl = host + "/list/$id.html";
if(/#top1/.test(baseUrl)){
  push(bookList, top1, topUrl)
} else if(/#top2/.test(baseUrl)){
  push(bookList, top2, topUrl)
} else {
  let lst = java.getElements(".lkpic_list li,.singer_list li")
  for(let i = 0; i < lst.size(); i++){
  	  bookList.push(lst.get(i).html())
  	}
}

